extern void wimptextop_paint(
	wimptextop_paint_flags flags,
	char const *s,
	int x0,
	int y0
);

#define RESULTS_LINE_INSET 12

/* Plot a piece of text in the redraw loop. */

static void results_plot_text(wimp_i icon, int ox, int y, char *text)
{
	wimptextop_paint_flags flags = wimptextop_GIVEN_BASELINE;
	int x;

	if (icon == RESULTS_ICON_TITLE_SHAPE) {
		x = ox + results_icons[icon].extent.x0 + RESULTS_LINE_INSET;
	} else {
		x = ox + results_icons[icon].extent.x1 - RESULTS_LINE_INSET;
		flags |= wimptextop_RJUSTIFY;
	}

	wimptextop_paint(flags, text, x, y + RESULTS_LINE_INSET);
}

static void results_redraw(wimp_draw *redraw)
{
	osbool more;
	int ox, oy, top, bottom, y0;

	/* Use the shape column to size the row heights. */

	int row_height = results_icons[RESULTS_ICON_TITLE_SHAPE].extent.y1 -
			results_icons[RESULTS_ICON_TITLE_SHAPE].extent.y0;

	/* Redraw the window. */

	more = wimp_redraw_window(redraw);

	wimp_set_colour(wimp_COLOUR_BLACK);
	wimp_set_colour(wimp_COLOUR_VERY_LIGHT_GREY | 0x80u);

	while (more) {
		ox = redraw->box.x0 - redraw->xscroll;
		oy = redraw->box.y1 - redraw->yscroll;

		top = (oy - redraw->clip.y1) / row_height;
		if (top < 1)
			top = 1;

		bottom = ((oy - redraw->clip.y0) - 1) / row_height;
		if (bottom > RESULTS_MAX_ROWS)
			bottom = RESULTS_MAX_ROWS;

		if (bottom > results_row_count)
			bottom = results_row_count;

		for (int y = top; y <= bottom; y++) {
			y0 = oy - ((y + 1) * row_height);

			results_plot_text(RESULTS_ICON_TITLE_SHAPE, ox, y0, results_rows[y - 1].shape);
			results_plot_text(RESULTS_ICON_TITLE_SIDES, ox, y0, results_rows[y - 1].sides);
			results_plot_text(RESULTS_ICON_TITLE_INTERNAL_ANGLES, ox, y0, results_rows[y - 1].internal_angle);
			results_plot_text(RESULTS_ICON_TITLE_SIDE_LENGTH, ox, y0, results_rows[y - 1].side_length);
			results_plot_text(RESULTS_ICON_TITLE_PERIMETER, ox, y0, results_rows[y - 1].perimeter);
			results_plot_text(RESULTS_ICON_TITLE_AREA, ox, y0, results_rows[y - 1].area);
		}

		more = wimp_get_rectangle(redraw);
	}
}

extern void wimptextop_set_colour(
	os_colour fg,
	os_colour bg
);

extern void wimp_set_colour(
	wimp_colour colour
);

static void results_redraw(wimp_draw *redraw)
{
	osbool more;
	int ox, oy, top, bottom, y1;

	/* Use the shape column to size the row heights. */

	int row_height = results_icons[RESULTS_ICON_TITLE_SHAPE].extent.y1 -
			results_icons[RESULTS_ICON_TITLE_SHAPE].extent.y0;

	/* Redraw the window. */

	more = wimp_redraw_window(redraw);

	wimp_set_colour(wimp_COLOUR_BLACK);

	while (more) {
		ox = redraw->box.x0 - redraw->xscroll;
		oy = redraw->box.y1 - redraw->yscroll;

		top = (oy - redraw->clip.y1) / row_height;
		if (top < 1)
			top = 1;

		bottom = ((oy - redraw->clip.y0) - 1) / row_height;
		if (bottom > RESULTS_MAX_ROWS)
			bottom = RESULTS_MAX_ROWS;

		if (bottom > results_row_count)
			bottom = results_row_count;

		for (int y = top; y <= bottom; y++) {
			y1 = oy - (y * row_height);

			os_plot(os_MOVE_TO, ox + RESULTS_LINE_INSET, y1 - RESULTS_LINE_INSET);

			printf("%-8s %4s  %14s  %14s  %14s  %14s",
					results_rows[y - 1].shape,
					results_rows[y - 1].sides,
					results_rows[y - 1].internal_angle,
					results_rows[y - 1].side_length,
					results_rows[y - 1].perimeter,
					results_rows[y - 1].area
			);
		}

		more = wimp_get_rectangle(redraw);
	}
}

static void results_redraw(wimp_draw *redraw)
{
	osbool more;
	int oy, top, bottom, icon_y0, icon_y1;

	/* Use the shape column to size the row heights. */

	int row_height = results_icons[RESULTS_ICON_TITLE_SHAPE].extent.y1 -
			results_icons[RESULTS_ICON_TITLE_SHAPE].extent.y0;

	/* Redraw the window. */

	more = wimp_redraw_window(redraw);

	while (more) {
		oy = redraw->box.y1 - redraw->yscroll;

		top = (oy - redraw->clip.y1) / row_height;
		if (top < 1)
			top = 1;

		bottom = ((oy - redraw->clip.y0) - 1) / row_height;
		if (bottom > RESULTS_MAX_ROWS)
			bottom = RESULTS_MAX_ROWS;

		if (bottom > results_row_count)
			bottom = results_row_count;

		for (int y = top; y <= bottom; y++) {
			icon_y1 = -(y * row_height);
			icon_y0 = icon_y1 - row_height;

			wimp_set_colour(wimp_COLOUR_VERY_DARK_GREY);

			os_plot(os_MOVE_TO, redraw->clip.x0, oy + icon_y0);
			os_plot(os_PLOT_TO, redraw->clip.x1, oy + icon_y0);

			results_plot_icon(RESULTS_ICON_ROW_SHAPE, icon_y0, icon_y1, results_rows[y - 1].shape);
			results_plot_icon(RESULTS_ICON_ROW_SIDES, icon_y0, icon_y1, results_rows[y - 1].sides);
			results_plot_icon(RESULTS_ICON_ROW_INTERNAL_ANGLES, icon_y0, icon_y1, results_rows[y - 1].internal_angle);
			results_plot_icon(RESULTS_ICON_ROW_SIDE_LENGTH, icon_y0, icon_y1, results_rows[y - 1].side_length);
			results_plot_icon(RESULTS_ICON_ROW_PERIMETER, icon_y0, icon_y1, results_rows[y - 1].perimeter);
			results_plot_icon(RESULTS_ICON_ROW_AREA, icon_y0, icon_y1, results_rows[y - 1].area);
		}

		more = wimp_get_rectangle(redraw);
	}
}

static void results_redraw(wimp_draw *redraw)
{
	osbool more;
	int oy, top, bottom, icon_y0, icon_y1;

	/* Use the shape column to size the row heights. */

	int row_height = results_icons[RESULTS_ICON_TITLE_SHAPE].extent.y1 -
			results_icons[RESULTS_ICON_TITLE_SHAPE].extent.y0;

	/* Redraw the window. */

	more = wimp_redraw_window(redraw);

	while (more) {
		oy = redraw->box.y1 - redraw->yscroll;

		top = (oy - redraw->clip.y1) / row_height;
		if (top < 0)
			top = 0;

		bottom = ((oy - redraw->clip.y0) - 1) / row_height;
		if (bottom > RESULTS_MAX_ROWS)
			bottom = RESULTS_MAX_ROWS;

		for (int y = top; y <= bottom; y++) {
			icon_y1 = -(y * row_height);
			icon_y0 = icon_y1 - row_height;

			wimp_set_colour((y % 2) ? wimp_COLOUR_WHITE : wimp_COLOUR_LIGHT_GREY);

			os_plot(os_MOVE_TO, redraw->clip.x0, oy + icon_y0);
			os_plot(os_PLOT_TO | os_PLOT_RECTANGLE, redraw->clip.x1 - 1, oy + icon_y1 - 1);

			if (y < 1 || y > results_row_count)
				continue;

			results_plot_icon(RESULTS_ICON_ROW_SHAPE, icon_y0, icon_y1, results_rows[y - 1].shape);
			results_plot_icon(RESULTS_ICON_ROW_SIDES, icon_y0, icon_y1, results_rows[y - 1].sides);
			results_plot_icon(RESULTS_ICON_ROW_INTERNAL_ANGLES, icon_y0, icon_y1, results_rows[y - 1].internal_angle);
			results_plot_icon(RESULTS_ICON_ROW_SIDE_LENGTH, icon_y0, icon_y1, results_rows[y - 1].side_length);
			results_plot_icon(RESULTS_ICON_ROW_PERIMETER, icon_y0, icon_y1, results_rows[y - 1].perimeter);
			results_plot_icon(RESULTS_ICON_ROW_AREA, icon_y0, icon_y1, results_rows[y - 1].area);
		}

		more = wimp_get_rectangle(redraw);
	}
}
